// ============ FILL YOUR KEYS IN HERE (inside n8n, not in a file) ============
// This workflow lives in a public repo. A key in a JSON file is a key on the
// internet, so paste them in the n8n editor where they stay in n8n's own DB.
const KEYS = {
  producthunt: '',   // free developer token: api.producthunt.com -> your app
  apify:       '',   // Apify API token — only if useG2Scraper is true
  linkfinder:  '',   // LinkFinder AI API key
  instantly:   ''    // Instantly API key
};

// Three sources, all optional, all emitting the same shape.
//
// G2's own API returned 401 on every auth style we tried, so the G2 route
// here goes through an Apify actor instead. It is still G2 data — the
// category and the review count — which is what made G2 worth having: the
// opener can say "you are listed in X with N reviews" and be checkable in
// one click.
//
// The honest trade: G2 sits behind Cloudflare, so a scraper breaks without
// warning, and it is against their terms. That is why it is off by default
// and why the other two exist — a broken scraper should cost you a smaller
// day, not a dead pipeline.
//
// Hacker News needs no key at all, so the run works before you have created
// any token.
return [{ json: {
  keys: KEYS,

  usePH: true,     // Product Hunt (free token)
  useHN: true,     // Hacker News (no auth)

  // G2 via Apify. Off by default: costs money, and a scraper against
  // Cloudflare is the one source here that can break silently.
  useG2Scraper: false,
  apifyActor: 'maximedupre~g2-products-scraper',
  g2Categories: ['website-privacy-auditing-tools','ai-interview-agent','site-search-software'],
  g2MinReviews: 10, g2MaxReviews: 250,

  campaignId: 'df17f3eb-368d-415f-99ab-b6a7325dad3c',
  batchSize: 10,
  topUpBelow: 40,
  maxAttempts: 3,

  // Product Hunt: recent enough to still be small, popular enough to be real.
  phMinVotes: 30, phMaxVotes: 1200, phMaxAgeDays: 400,
  // Hacker News: Show HN posts clearing a modest bar.
  hnMinPoints: 20,

  excludeDomains: [
    'linkfinderai.com','clay.com','warmly.ai','6sense.com','apollo.io',
    'zoominfo.com','lusha.com','cognism.com','hunter.io','snov.io',
    'rocketreach.co','seamless.ai','uplead.com','findymail.com','dropcontact.com',
    'kaspr.io','surfe.com','prospeo.io','anymailfinder.com','tryprofound.com',
    'peec.ai','otterly.ai','athenahq.ai','scrunchai.com','goodie.ai','brandlight.ai'
  ],
  excludeHosts: [
    'producthunt.com','github.com','gitlab.com','medium.com','substack.com',
    'notion.so','notion.site','youtube.com','twitter.com','x.com',
    'news.ycombinator.com','reddit.com','linkedin.com','vercel.app',
    'netlify.app','herokuapp.com','pages.dev','webflow.io'
  ]
} }];

// Set up the queue and check the keys. Nothing else gates a run.
//
// The queue lives in n8n's own workflow storage. No database to set up, it
// survives restarts, and it is what makes the pipeline reliable: a domain
// that does not resolve this hour is simply still there next hour.
const cfg = $('Config').first().json;

// Catch an unset key here rather than as a confusing 401 further downstream.
const k = cfg.keys || {};
const missing = [];
if (!k.instantly)  missing.push('instantly');
if (!k.linkfinder) missing.push('linkfinder');
if (cfg.usePH && !k.producthunt) missing.push('producthunt (or set usePH:false)');
if (cfg.useG2Scraper && !k.apify) missing.push('apify (or set useG2Scraper:false)');
if (missing.length) {
  throw new Error('Open the Config node and fill in: ' + missing.join(', ') +
    '. Keys go in the KEYS object at the top.');
}

const store = $getWorkflowStaticData('global');
store.queue = store.queue || [];
store.done  = store.done  || {};
store.stats = store.stats || { pushed: 0, dead: 0, retries: 0, runs: 0 };
store.stats.runs++;

return [{ json: { ...cfg,
  queueLength: store.queue.length,
  needsTopUp: store.queue.length < cfg.topUpBelow
} }];

// Both sources -> the queue, each carrying a sentence that is true of it.
//
// THE OBSERVATION FIELD IS THE POINT.
// The opener has to name something real about the prospect. Hard-coding
// "on G2" in the copy was fine while G2 was the only source; the moment a
// lead arrives from somewhere else that line is a lie to a real person.
// So the sentence is built HERE, where the source is known, and shipped as
// one merge field. The campaign renders {{observation}} and is true by
// construction no matter which source found the company.
const cfg = $('Plan this run').first().json;
const store = $getWorkflowStaticData('global');
const seen = new Set([...store.queue.map(q => q.domain), ...Object.keys(store.done)]);

const bad = d => cfg.excludeDomains.includes(d) ||
  cfg.excludeHosts.some(h => d === h || d.endsWith('.' + h));

const host = u => {
  try { return new URL(u || '').hostname.toLowerCase().replace(/^www\./, ''); }
  catch { return ''; }
};

let added = 0;
const push = row => {
  if (!row.domain || seen.has(row.domain) || bad(row.domain)) return;
  seen.add(row.domain); added++;
  store.queue.push({ ...row, attempts: 0 });
};

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;

  // --- Product Hunt ----------------------------------------------------
  const edges = body?.data?.posts?.edges;
  if (Array.isArray(edges)) {
    const now = Date.now();
    for (const e of edges) {
      const n = e?.node; if (!n) continue;
      const d = host(n.website);
      const votes = n.votesCount || 0;
      if (votes < cfg.phMinVotes || votes > cfg.phMaxVotes) continue;
      const age = (now - new Date(n.createdAt).getTime()) / 86400000;
      if (!isFinite(age) || age > cfg.phMaxAgeDays) continue;
      const topic = n.topics?.edges?.[0]?.node?.name || '';
      const company = n.name || d;
      push({
        domain: d, company, source: 'producthunt',
        category: topic || 'software',
        observation: `I came across ${company} on Product Hunt — ${votes} upvotes`
          + (topic ? ` under ${topic}` : '') + '.'
      });
    }
  }

  // --- G2 via Apify -----------------------------------------------------
  // Apify actors disagree about field names, and apify.com is unreachable
  // from where this was written, so nothing here assumes one spelling. If
  // the run produces zero G2 rows, log one dataset item and add its keys.
  const rows = Array.isArray(body) ? body : (Array.isArray(body?.items) ? body.items : null);
  if (rows && rows.length && rows[0] && !rows[0].hits && !rows[0].data) {
    for (const r of rows) {
      const d = host(r.domain || r.website || r.url || r.productUrl || '')
             || String(r.domain || '').toLowerCase().replace(/^www\./, '');
      const reviews = Number(r.review_count ?? r.reviewCount ?? r.reviews ?? r.reviewsCount ?? 0);
      const category = r.category || r.categoryName || r.category_name || 'software';
      const company = r.name || r.productName || r.product || d;
      if (!d) continue;
      if (reviews < cfg.g2MinReviews || reviews > cfg.g2MaxReviews) continue;
      push({
        domain: d, company, source: 'g2',
        category,
        observation: `You are listed on G2 under ${category} with ${reviews} reviews.`
      });
    }
  }

  // --- Hacker News ------------------------------------------------------
  if (Array.isArray(body?.hits)) {
    for (const h of body.hits) {
      const pts = h.points || 0;
      if (pts < cfg.hnMinPoints) continue;
      const d = host(h.url);
      const company = (String(h.title || '').replace(/^show hn:?\s*/i, '')
        .split(/[\u2013\u2014\-:|,]/)[0] || d).trim();
      push({
        domain: d, company: company || d, source: 'hackernews',
        category: 'software',
        observation: `I saw ${company || d} on Show HN — ${pts} points.`
      });
    }
  }
}

return [{ json: { ...cfg, added, queueLength: store.queue.length } }];

// Take this hour's batch off the queue.
//
// Oldest first, and anything that has burned through maxAttempts is written
// off here rather than retried forever. A domain with no reachable decision
// maker is not going to grow one.
const cfg = $('Plan this run').first().json;
const store = $getWorkflowStaticData('global');
const take = Math.min(cfg.batchSize, store.queue.length);

const batch = [];
while (batch.length < take && store.queue.length) {
  const row = store.queue.shift();
  if (!row) break;
  if ((row.attempts || 0) >= cfg.maxAttempts) {
    store.done[row.domain] = 'gave_up';
    store.stats.dead++;
    continue;
  }
  batch.push({ json: { ...row, campaignId: cfg.campaignId } });
}

if (!batch.length) {
  return [{ json: { idle: true, queueLength: store.queue.length,
    note: 'nothing to enrich this hour' } }];
}
return batch;

// Sort the answer into: usable, retry later, or written off.
//
// This endpoint answers HTTP 200 / "success" even when its upstream is
// down, putting a status message where a person should be:
//   {"personId": null, "name": "We are on maintenance. Check back in 48hrs"}
// Measured across ~20 live calls: roughly HALF. So the sentinel is not an
// error to report, it is a "not now" to reschedule.
//
// ORDER MATTERS. Look for a real person FIRST. The actor also injects a
// chatty banner row alongside genuine results, so checking sentinels first
// throws away a good lead and pays to look it up again.
const OUTAGE = ['maintenance','check back in','we improve the actor','contact us if you are having'];
const store = $getWorkflowStaticData('global');
const row = $('One at a time').first().json;

const body = $input.first().json;
const payload = body?.body ?? body;
let rows = payload?.result ?? payload?.employees ?? payload;
while (rows && !Array.isArray(rows) && rows.result) rows = rows.result;
if (!Array.isArray(rows)) rows = [];

const person = rows.find(r => r && (r.personId || r.person_id) &&
  r.email && String(r.email).includes('@') && r.name);

if (person) {
  const parts = String(person.name).trim().split(/\s+/);
  return [{ json: { ...row, status: 'ok', email: person.email.trim(),
    firstName: parts[0], lastName: parts.slice(1).join(' '),
    title: person.jobTitle || person.job_title || '' } }];
}

const sentinel = rows.find(r => r && !r.personId && !r.person_id &&
  OUTAGE.some(m => String(r.name || '').toLowerCase().includes(m)));

if (sentinel) {
  // Not this company's fault. Back on the queue, try again next hour.
  store.queue.push({ ...row, attempts: (row.attempts || 0) + 1 });
  store.stats.retries++;
  return [{ json: { ...row, status: 'requeued' } }];
}

// A real, empty answer. Nobody reachable here; stop paying to ask.
store.done[row.domain] = 'no_person';
store.stats.dead++;
return [{ json: { ...row, status: 'no_person' } }];

// Record the outcome of the push.
//
// A failed upload is deliberately put BACK on the queue: we already paid to
// enrich this lead, so it is the single most valuable thing to retry. A
// successful one is marked done so it is never sourced or enriched again.
const store = $getWorkflowStaticData('global');
const row = $('Usable?').first().json;
const res = $input.first().json;
const code = res?.statusCode ?? res?.status ?? 200;
const ok = !(code >= 400) && !res?.error;

if (ok) {
  store.done[row.domain] = row.email;
  store.stats.pushed++;
  return [{ json: { domain: row.domain, email: row.email, status: 'pushed' } }];
}

store.queue.push({ ...row, attempts: (row.attempts || 0) + 1 });
return [{ json: { domain: row.domain, status: 'push_failed_requeued',
  detail: JSON.stringify(res).slice(0, 200) } }];

// End-of-run summary. Read this in n8n's execution list to see whether the
// pipeline is healthy without opening anything.
const store = $getWorkflowStaticData('global');
const s = store.stats || {};
return [{ json: {
  queueRemaining: store.queue.length,
  finished: Object.keys(store.done).length,
  pushedTotal: s.pushed || 0,
  wroteOff: s.dead || 0,
  retriesSoFar: s.retries || 0,
  runs: s.runs || 0
} }];

const cfg = $input.first().json;
// No Product Hunt token -> emit nothing, so the request node never runs and
// never asks for a key that is not there. Hacker News carries the run alone.
if (!cfg.usePH || !(cfg.keys||{}).producthunt) return [];
return [{ json: cfg }];

const cfg = $input.first().json;
// Off, or no Apify token -> emit nothing and the actor is never called.
if (!cfg.useG2Scraper || !(cfg.keys||{}).apify) return [];
return [{ json: cfg }];
